import{_ as e,c as o,o as t,a2 as a}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"ADR: ModuleRoute Hot-Path Contract","description":"","frontmatter":{"sidebarPos":16,"sidebarTitle":"ADR — ModuleRoute Hot Path"},"headers":[],"relativePath":"system-reference/adr-module-route-hot-path.md","filePath":"system-reference/adr-module-route-hot-path.md","lastUpdated":1786482899000}'),s={name:"system-reference/adr-module-route-hot-path.md"},r=a(`<h1 id="adr-moduleroute-hot-path-contract" tabindex="-1">ADR: ModuleRoute Hot-Path Contract <a class="header-anchor" href="#adr-moduleroute-hot-path-contract" aria-label="Permalink to &quot;ADR: ModuleRoute Hot-Path Contract&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-08-11</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>ModuleRoute</code> is the intended first-class API for module routes (sidebar, controllers, inspect, Blueprint). Early wiring that forced <strong>every</strong> hot-path call through <code>ModuleRouteRegistry</code> (and eager construct / presentation) roughly <strong>doubled</strong> admin document request time (~3s → ~7s) in production-like local measurements.</p><p>Root causes observed:</p><ol><li>Sidebar / route boot calling <code>$module-&gt;isSingleton()</code> which delegated into <strong>registry + materialization</strong> for every route.</li><li><code>hasRoute</code> / <code>getRouteNames</code> going through registry <code>names()</code> (union + sort) instead of activator status keys.</li><li><code>CoreController::__construct</code> eagerly resolving <code>ModuleRoute</code> — runs during <code>RouteServiceProvider</code> <code>additionalRoutes</code> <code>app()-&gt;make($controller)</code> for every controller when <code>route:cache</code> is absent.</li><li><code>getConfigFieldsByRoute</code> always going through Blueprint/presentation resolution on large configs (e.g. PressRelease).</li></ol><p>Hardcoding sidebar <code>isSingleton</code> to <code>false</code> did <strong>not</strong> change latency — proving the cost was broader than navigation alone.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Adopt a <strong>hot-path contract</strong>: consumers may use the <code>ModuleRoute</code> <strong>object API</strong>, but implementations must keep request-critical work <strong>lazy, memoized, and raw-first</strong>. Registry and Blueprint are not free.</p><h3 id="principle" tabindex="-1">Principle <a class="header-anchor" href="#principle" aria-label="Permalink to &quot;Principle&quot;">​</a></h3><table><thead><tr><th>Layer</th><th>Role</th></tr></thead><tbody><tr><td><strong>API surface</strong></td><td>Prefer <code>ModuleRoute</code> (<code>$module-&gt;moduleRoute(&#39;Post&#39;)-&gt;…</code>) for domain readability</td></tr><tr><td><strong>Hot-path cost</strong></td><td>Must match (or beat) pre-ModuleRoute activator / class-string / <code>data_get</code> costs</td></tr><tr><td><strong>Registry</strong></td><td>Lazy, request-scoped instance cache — for inspect, explicit domain use, opt-in presentation</td></tr><tr><td><strong>Module facades</strong></td><td>May share helpers with <code>ModuleRoute</code> but <strong>must not</strong> require registry on spam paths</td></tr></tbody></table><h3 id="cost-table-normative" tabindex="-1">Cost table (normative) <a class="header-anchor" href="#cost-table-normative" aria-label="Permalink to &quot;Cost table (normative)&quot;">​</a></h3><table><thead><tr><th>Operation</th><th>Allowed hot-path cost</th><th>Forbidden on hot path</th></tr></thead><tbody><tr><td><code>isSingleton</code></td><td>Class-string <code>class_exists</code> + <code>classHasTrait</code> + <strong>memo</strong></td><td><code>App::make(repository)</code>, model instantiate, new registry per call</td></tr><tr><td><code>isEnabled</code> / <code>isEnabledRoute</code></td><td>Activator <code>hasStatus</code> (filesystem default)</td><td><code>Modularous::findOrFail</code> + store indirection per call</td></tr><tr><td><code>hasRoute</code> / <code>getRouteNames</code></td><td>Activator status <strong>keys</strong> + Module memo</td><td><code>ModuleRouteRegistry::names()</code> union/sort as default</td></tr><tr><td>Config field read (edit form)</td><td>Preloaded raw / nested-first <code>data_get</code> / flat</td><td>Presentation resolver unless Blueprint meta / non-config driver</td></tr><tr><td>Controller construct</td><td>Module + <code>routeName</code> only</td><td>Eager <code>$this-&gt;getModuleRoute()</code></td></tr><tr><td>Sidebar listing</td><td><strong><code>getRawRouteConfigs</code> + <code>Module::isSingleton</code></strong> only</td><td><code>sidebarRoutes()</code> / <code>moduleRoute()</code> / <code>moduleRoutes()</code> for menu build</td></tr><tr><td><code>hasTable</code> / <code>features()</code></td><td>Lazy, inspect / doctor / rare</td><td>Sidebar, route boot, every <code>getConfigFieldsByRoute</code></td></tr></tbody></table><h3 id="moduleroute-instance-rules" tabindex="-1">ModuleRoute instance rules <a class="header-anchor" href="#moduleroute-instance-rules" aria-label="Permalink to &quot;ModuleRoute instance rules&quot;">​</a></h3><ol><li><strong>Construct is cheap</strong> — no config load, no trait scan, no Schema.</li><li><strong><code>rawConfig()</code> / <code>config()</code> lazy</strong> — load once per instance; prefer raw for hot reads.</li><li><strong><code>isSingleton()</code> memo</strong> — class-string only (same helper as <code>Module::isSingleton</code> when possible).</li><li><strong><code>presentation()</code> / Blueprint</strong> — only when: <ul><li>global <code>module_route_presentation.driver</code> ≠ <code>config</code>, or</li><li>route has <code>blueprint</code> / <code>presentation</code> meta, or</li><li>nested <code>index</code>/<code>form</code> leaf is a class string / driver meta array.</li></ul></li><li><strong>Instance cache</strong> — <code>ModuleRouteRegistry::find</code> / <code>make</code> caches per Module per request.</li><li><strong><code>moduleRoute($name)</code> is O(1) after warm</strong> — <code>moduleRoutes()</code> may remain expensive (inspect OK).</li></ol><h3 id="controller-rules" tabindex="-1">Controller rules <a class="header-anchor" href="#controller-rules" aria-label="Permalink to &quot;Controller rules&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__construct          → module, routeName/moduleRouteName, repository</span></span>
<span class="line"><span>preload              → MUST NOT resolve ModuleRoute (no-op)</span></span>
<span class="line"><span>getRouteConfig / inputs / headers → raw Module getters; use ModuleRoute only if already set</span></span>
<span class="line"><span>getConfigFieldsByRoute → raw/data_get first; ModuleRoute presentation only if shouldUse…</span></span>
<span class="line"><span>URL / prefix         → may use ModuleRoute only when already resolved; never force registry</span></span>
<span class="line"><span>getModuleRoute()     → lazy resolve on explicit call only</span></span></code></pre></div><p>Never resolve <code>ModuleRoute</code> solely because <code>additionalRoutes</code> instantiates the controller. Never call <code>ensureModuleRouteResolved()</code> from preload, config getters, or default URL helpers.</p><h3 id="sidebar-rules" tabindex="-1">Sidebar rules <a class="header-anchor" href="#sidebar-rules" aria-label="Permalink to &quot;Sidebar rules&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OK:  getRawRouteConfigs(valid) + Module::isSingleton($name)   ← ModularousNavigation MUST use this</span></span>
<span class="line"><span>NO:  sidebarRoutes() / moduleRoute() for every menu render     ← still builds registry + FeatureDetector per module (~0.5–1s)</span></span>
<span class="line"><span>NO:  moduleRoutes() / enabledModuleRoutes() for menu render</span></span>
<span class="line"><span>NO:  headline() that forces features()/hasTable()</span></span></code></pre></div><p><code>Module::sidebarRoutes()</code> remains available for inspect / explicit ModuleRoute consumers — <strong>not</strong> for admin sidebar hot path until registry construct is free.</p><p><code>headline()</code> must prefer configured string before singleton detection.</p><h3 id="shared-helpers-recommended" tabindex="-1">Shared helpers (recommended) <a class="header-anchor" href="#shared-helpers-recommended" aria-label="Permalink to &quot;Shared helpers (recommended)&quot;">​</a></h3><p>Avoid dual implementations:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Conceptual — Module owns memo; ModuleRoute delegates</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isSingleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($name)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// hot path entry</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ModuleRoute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isSingleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// calls same class-string + memo helper</span></span></code></pre></div><p>Same pattern for parent detection when both need it.</p><h3 id="migration-order-same-perf" tabindex="-1">Migration order (same perf) <a class="header-anchor" href="#migration-order-same-perf" aria-label="Permalink to &quot;Migration order (same perf)&quot;">​</a></h3><ol><li><strong>Keep sidebar on raw config</strong> — do not migrate navigation to ModuleRoute until measured parity.</li><li>Controllers may expose <code>getModuleRoute()</code> lazily; config/URL hot paths stay raw-first.</li><li>Nested <code>index</code>/<code>form</code> + Blueprint class extract — opt-in per route.</li><li>Drop unused flat config leaves after class source of truth.</li></ol><p>Do <strong>not</strong> set global presentation driver to <code>class</code> for all routes as a first step.</p><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><p>When changing ModuleRoute hot paths:</p><ol><li>Measure admin <strong>document</strong> request (e.g. edit) with changes on vs stashed — target parity with post-fix baseline (~raw config path).</li><li>Isolating one call site (e.g. sidebar singleton → <code>false</code>) must not be the only proof; also check construct + <code>getConfigFieldsByRoute</code> + boot without <code>route:cache</code>.</li><li>Keep package tests for enable/disable (same activator instance on filesystem driver) and presentation nested/legacy fallback.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>Module::hasRoute</code> / <code>getRouteNames</code> / <code>isSingleton</code> / <code>isEnabled*</code> stay <strong>registry-free</strong> on filesystem default.</li><li><code>CoreController</code> does not eager-load <code>ModuleRoute</code> in <code>__construct</code> or preload.</li><li>Admin sidebar stays on raw config arrays (never <code>sidebarRoutes()</code>).</li><li><code>getConfigFieldsByRoute</code> uses <code>shouldUseModuleRoutePresentation()</code> (or equivalent) before Blueprint path.</li><li><code>ModuleRouteRegistry::find</code> resolves config-listed names without forcing status∪config union.</li><li>Docs and agents treat this ADR as binding when wiring sidebar/controllers to ModuleRoute.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><ul><li>Making <code>moduleRoutes()</code> as cheap as <code>getRouteNames()</code> (inspect may pay full materialization).</li><li>Removing <code>config.php</code> in the same change set as API migrate.</li><li>Database status driver matching filesystem hot-path cost (DB is explicitly opt-in).</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/console/module/module-route">ModuleRoute</a></li><li><a href="/guide/console/module/module-route-blueprint">ModuleRoute Blueprint</a></li><li><a href="./adr-module-route-blueprint">ADR — ModuleRoute Blueprint</a></li><li><a href="/guide/console/module/route-inspect">Route Inspect</a></li></ul>`,38),n=[r];function i(d,l,c,u,h,p){return t(),o("div",null,n)}const f=e(s,[["render",i]]);export{m as __pageData,f as default};
